import { Offering } from './offering/entities/offeringPackage.entity.js';
import { InvoiceLineItems } from './invoice/entities/invoice.entity.js';
import { OfferingType } from './offering/entities/OfferingType.js';
import { ValidBillingCycles } from './offering/dto/createOffering.dto.js';
import { SupportedCurrencies } from './offering/dto/SupportedCurrencies.js';
import { FreeDimensionOnInvoice } from './setting/dto/FreeDimensionOnInvoice.js';
import { ReadSettingsResponseData } from './setting/dto/read-setting.dto.js';
import {
    aggregationInterval,
    aggregationMethod,
    countBasedUnits,
    overageAllowedEnum,
    roundingEnum,
} from './dimensions/dto/create-dimension.dto.js';

const dim = (over: Record<string, unknown>) => ({
    dimensionId: over['dimensionId'] as string,
    dimensionName: over['dimensionId'] as string,
    aggregationInterval: aggregationInterval.hour,
    aggregationMethod: aggregationMethod.sum,
    usageIncrement: '1',
    rounding: roundingEnum.round,
    consumptionUnit: { unit: countBasedUnits['count-based'], type: 'count' as const },
    ...over,
});

const run = async (dimensions, usage, settings?: ReadSettingsResponseData) => {
    const lineItems = new InvoiceLineItems();
    await Offering.getLineItemsForUsage({
        startDate: new Date('2026-07-01'),
        endDate: new Date('2026-08-01'),
        lineItems,
        negative: false,
        businessID: 'b',
        customerId: 'c',
        customerService: undefined,
        dimensions,
        offeringInstance: Offering.getInstance(
            {
                offeringId: 'o',
                offeringName: 'Plan',
                offeringType: OfferingType.usageBased,
                currency: SupportedCurrencies.USD,
                billingCycle: ValidBillingCycles.monthly,
                dimensions,
            } as never,
            'c',
            'b',
            undefined,
            settings,
            undefined,
            undefined,
            undefined,
            usage,
        ),
    });
    return lineItems.getLineItems().map((l) => [l.name, l.quantity, l.unitCost]);
};

const usageOf = (dimensionId: string, values: number[]) => ({
    offeringId: 'o',
    dimensionId,
    usage: values.map((v) => ({ value: String(v), startTime: '2026-07-02T00:00:00Z', endTime: '2026-07-02T00:00:00Z' })),
});

describe('edge cases', () => {
    test('finite exhausted allowance with overage charges only the excess', async () => {
        expect(
            await run(
                [dim({ dimensionId: 'a', consumptionPrice: '2', usageEntitlement: 10, overageAllowed: overageAllowedEnum.true })],
                [usageOf('a', [6, 7])],
            ),
        ).toEqual([['a - Plan', 3, 2]]);
    });
    test('unexhausted allowance charges nothing and gets no line', async () => {
        expect(
            await run(
                [dim({ dimensionId: 'a', consumptionPrice: '2', usageEntitlement: 10, overageAllowed: overageAllowedEnum.true })],
                [usageOf('a', [4])],
            ),
        ).toEqual([]);
    });
    test('exactly exhausted allowance charges nothing', async () => {
        expect(
            await run(
                [dim({ dimensionId: 'a', consumptionPrice: '2', usageEntitlement: 10, overageAllowed: overageAllowedEnum.true })],
                [usageOf('a', [10])],
            ),
        ).toEqual([]);
    });
    test('unlimited allowance charges nothing', async () => {
        expect(
            await run(
                [dim({ dimensionId: 'a', consumptionPrice: '2', usageEntitlement: 'inf', overageAllowed: overageAllowedEnum.true })],
                [usageOf('a', [1000])],
            ),
        ).toEqual([]);
    });
    test('overage forbidden charges nothing', async () => {
        expect(
            await run(
                [dim({ dimensionId: 'a', consumptionPrice: '2', usageEntitlement: 10, overageAllowed: overageAllowedEnum.false })],
                [usageOf('a', [1000])],
            ),
        ).toEqual([]);
    });
    test('overage unspecified charges nothing', async () => {
        expect(
            await run([dim({ dimensionId: 'a', consumptionPrice: '2', usageEntitlement: 10 })], [usageOf('a', [1000])]),
        ).toEqual([]);
    });
    test('string allowance is understood', async () => {
        expect(
            await run(
                [dim({ dimensionId: 'a', consumptionPrice: '2', usageEntitlement: '10', overageAllowed: overageAllowedEnum.true })],
                [usageOf('a', [12])],
            ),
        ).toEqual([['a - Plan', 2, 2]]);
    });
    test('zero allowance charges everything', async () => {
        expect(
            await run(
                [dim({ dimensionId: 'a', consumptionPrice: '2', usageEntitlement: 0, overageAllowed: overageAllowedEnum.true })],
                [usageOf('a', [3])],
            ),
        ).toEqual([['a - Plan', 3, 2]]);
    });
    test('no allowance charges everything', async () => {
        expect(await run([dim({ dimensionId: 'a', consumptionPrice: '2' })], [usageOf('a', [3])])).toEqual([
            ['a - Plan', 3, 2],
        ]);
    });
    test('priced dimension with no usage gets no line', async () => {
        expect(await run([dim({ dimensionId: 'a', consumptionPrice: '2' })], [usageOf('a', [])])).toEqual([]);
    });
    test('zero priced dimension is shown by default', async () => {
        expect(await run([dim({ dimensionId: 'a', consumptionPrice: '0' })], [usageOf('a', [7])])).toEqual([
            ['a - Plan', 7, 0],
        ]);
    });
    test('zero priced dimension hidden when settings hide free dimensions', async () => {
        expect(
            await run([dim({ dimensionId: 'a', consumptionPrice: '0' })], [usageOf('a', [7])], {
                freeDimensionOnInvoice: FreeDimensionOnInvoice.hide,
            } as ReadSettingsResponseData),
        ).toEqual([]);
    });
    test('zero priced dimension shown when settings show free dimensions', async () => {
        expect(
            await run([dim({ dimensionId: 'a', consumptionPrice: '0' })], [usageOf('a', [7])], {
                freeDimensionOnInvoice: FreeDimensionOnInvoice.show,
            } as ReadSettingsResponseData),
        ).toEqual([['a - Plan', 7, 0]]);
    });
    test('mixed dimensions', async () => {
        expect(
            await run(
                [
                    dim({ dimensionId: 'paid', consumptionPrice: '0.5' }),
                    dim({ dimensionId: 'free', consumptionPrice: '0.00' }),
                    dim({ dimensionId: 'capped', consumptionPrice: '1', usageEntitlement: 5, overageAllowed: overageAllowedEnum.false }),
                    dim({ dimensionId: 'over', consumptionPrice: '1', usageEntitlement: 5, overageAllowed: overageAllowedEnum.true }),
                ],
                [usageOf('paid', [10]), usageOf('free', [2]), usageOf('capped', [9]), usageOf('over', [9])],
            ),
        ).toEqual([
            ['paid - Plan', 10, 0.5],
            ['free - Plan', 2, 0],
            ['over - Plan', 4, 1],
        ]);
    });
});
